/* Все p внутри .card */
.card p { color: #666; }

/* Только прямой потомок */
.card > p { font-weight: bold; }

/* Первый p сразу после h2 */
h2 + p { margin-top: 0; }

/* Все p после h2 на одном уровне */
h2 ~ p { color: blue; }

/* Есть атрибут href */
a[href] { color: blue; }

/* href точно равен значению */
a[href="https://example.com"] { font-weight: bold; }

/* href начинается с https */
a[href^="https"] { color: green; }

/* href заканчивается на .pdf */
a[href$=".pdf"]::after { content: " 📄"; }

/* href содержит tutorial */
a[href*="tutorial"] { color: orange; }

/* class содержит btn как отдельное слово */
[class~="btn"] { padding: 8px 16px; }

/* lang начинается на ru */
[lang|="ru"] { font-family: serif; }

/* Без :is() — долго */
header h1, header h2, header h3,
footer h1, footer h2, footer h3 {
  color: navy;
}

/* С :is() — короче */
:is(header, footer) :is(h1, h2, h3) {
  color: navy;
}

/* Базовые стили — легко переопределить */
:where(h1, h2, h3) {
  margin-top: 0;
}

/* Этот стиль перезапишет :where() */
.page-title h1 {
  margin-top: 2rem;
}

/* Все кнопки, кроме .disabled */
button:not(.disabled) {
  background: blue;
  color: white;
}

/* Все ссылки, кроме внешних */
a:not([href^="http"]) {
  color: inherit;
}

/* Карточка, которая содержит изображение */
.card:has(img) {
  display: grid;
  grid-template-columns: 200px 1fr;
}

/* Форма с ошибкой */
.form:has(.error) {
  border-color: red;
}
